// Boss stats page: the maths and wording on top of web/src/data/bosses.json (generated by scripts/build_bosses.py,
// shape in its header). Pure, so the unit tests cover it. Nothing here states a number the file or the event's
// ruleset doesn't hold: HP x modifier, HP left at a skull, ratios and sums are computed.

export interface BossAction {
  at: number;
  do: string[];
}
/** Armour (Dreadbloon GenerateArmour) / camo shield (Phayze CamoShield): HP rebuilt at every skull. */
export interface BossShield {
  action: string;
  health: number;
  per: "skull";
}
/** One decoded action model of a tier (build_bosses.py "actions"): the class name plus its own fields. */
export interface ActionModel {
  model: string;
  [field: string]: unknown;
}
/** A behaviour that isn't "run these at each skull" (build_bosses.py "passives"); only whitelisted fields are ever shown. */
export interface Passive {
  kind: string;
  [field: string]: unknown;
}
export interface BossTier {
  health: number;
  id: string;
  speed: number;
  skulls: BossAction[];
  triggers: BossAction[];
  shield?: BossShield;
  /** Dreadbloon: the tower sets it is immune to, length skulls + 1: [0] at spawn, [k] after skull k. */
  immunity?: string[];
  passives?: Passive[];
  actions?: Record<string, ActionModel[]>;
  /** action ids a skull runs that have no model in this tier: never mentioned */
  noModel?: string[];
}
export interface BossSpawnTier {
  health: number;
  id: string;
  speed: number;
  used: boolean;
}
export interface BossSpawn {
  key: string;
  name: string | null;
  normal: BossSpawnTier[];
  elite: BossSpawnTier[];
}
export interface BossInfo {
  name: string;
  desc: string[];
  tagline: string;
  tagline2: string;
  props: string[];
  normal: BossTier[];
  elite: BossTier[];
  spawns?: BossSpawn[];
}
export interface BossStatsData {
  bosses: Record<string, BossInfo>;
  speed: Record<string, number>;
  v: string;
  format: number;
}

/** A multiplier as the game's challenge editor shows it (and the rules panel): 0.9 → "90%". */
export const mult = (n: number) => `${+(n * 100).toFixed(1)}%`;

/** Event modifiers that apply to a boss: healthMultipliers.boss and bossSpeedMultiplier (1 = none). */
export interface BossMods {
  health: number;
  speed: number;
}
export const NO_BOSS_MODS: BossMods = { health: 1, speed: 1 };
export const modsChanged = (m: BossMods) => m.health !== 1 || m.speed !== 1;
export function bossMods(m: { healthMultipliers?: { boss?: number }; bossSpeedMultiplier?: number } | undefined): BossMods {
  const h = m?.healthMultipliers?.boss;
  const s = m?.bossSpeedMultiplier;
  return { health: typeof h === "number" && h > 0 ? h : 1, speed: typeof s === "number" && s > 0 ? s : 1 };
}

/** Tier HP with the event's boss health multiplier, whole HP. */
export const modHealth = (base: number, m: BossMods) => Math.round(base * m.health);
/** Speed (game units) with the event's boss speed multiplier. */
export const modSpeed = (base: number, m: BossMods) => base * m.speed;
/** Speed as a share of a Red bloon's: 1.25 vs Red 25 → 0.05. */
export const speedShare = (speed: number, red: number) => speed / red;

/** Shield HP with the event's boss health multiplier (like the boss HP), whole HP. */
export const shieldHp = (s: BossShield, m: BossMods) => Math.round(s.health * m.health);
/** The game's own names (its description text): Dreadbloon's "Ceramic Armor Shell", Phayze's "Reality Shield". */
export const shieldLabel = (s: BossShield) => (s.action === "GenerateArmour" ? "Ceramic Armor Shell" : "Reality Shield");
/** Short lowercase word for the stretch rows. */
export const shieldWord = (s: BossShield) => (s.action === "GenerateArmour" ? "shell" : "shield");
/** Shields are up at spawn: from play (owner, a player); the game data has no flag for it. */
export const SHIELD_UP_AT_SPAWN = true;

/** The extra gauge each boss draws next to the health bar (decoration only). */
export const BAR_EXTRA: Record<string, "armour" | "heat" | "tail"> = {
  dreadbloon: "armour",
  phayze: "armour",
  blastapopoulos: "heat",
  diamondback: "tail",
};

export interface SkullRow {
  /** skull number; 0 = the last stretch, from the last skull to defeat */
  n: number;
  at: number;
  /** boss HP to take off to get here from the previous skull (or from full health) */
  hp: number;
  /** shield HP to break on the way: up at spawn and rebuilt at every skull, so on every stretch */
  shield: number;
}
/** The stretch before each skull, then the one to defeat (HP and shield with the event modifier already applied). */
export function skullRows(hp: number, skulls: readonly BossAction[], shield = 0): SkullRow[] {
  const ats = [...skulls.map((s) => s.at), 0];
  let prev = hp;
  return ats.map((at, i) => {
    const left = Math.round(hp * at);
    const row = { n: i < skulls.length ? i + 1 : 0, at, hp: prev - left, shield: SHIELD_UP_AT_SPAWN || i ? shield : 0 };
    prev = left;
    return row;
  });
}

/** "Elite T5 = 8× Normal T5": the Elite / Normal ratio of a tier, one decimal at most. */
export const tierRatio = (elite: number, normal: number) => +(elite / normal).toFixed(1);

// ─────────────────────────────── skull action wording

/** Pure animation / sound / bookkeeping names: never shown. */
const DROP = new Set([
  "OnSkull",
  "PlayReArmourSound",
  "ReArmourSound",
  "ShieldAnim",
  "SkullDelay",
  "SkullAnim",
  "CreateStunEffect",
  "PlayStunSound",
  "InvulnerabilityDuration",
]);
const ACTION_TEXT: Record<string, string> = {
  AttkSpew: "Spews bloons",
  StrongSpawn: "Spawns strong bloons",
  WeakSpawn: "Spawns weak bloons",
  StrongSecondSpawn: "Second strong spawn",
  WeakerSpawn: "Spawns weaker bloons",
  AttkBleed: "Bleed attack",
  AddHeat: "Adds heat",
  Fireball: "Fireball",
  InvulnOn: "Becomes invulnerable",
  MakeInvulnerable: "Becomes invulnerable",
  PauseMoving: "Stops moving",
  PauseMovement: "Stops moving",
  RockTimer: "Rock timer",
  ApplyImmunity: "Gains an immunity",
  GenerateArmour: "Generates armour",
  SpawnRockBloons: "Spawns rock bloons",
  SpawnEliteRockBloons: "Spawns elite rock bloons",
  EtherealAnim: "Ethereal phase",
  RemoveMutators: "Removes buffs",
  SpeedDown: "Slows down",
  CamoShield: "Camo shield",
  RedirectBloons: "Redirects bloons",
  DestroyProjectiles: "Destroys projectiles",
  KnockBack: "Knockback",
  ReflectProjectiles: "Reflects projectiles",
  StunTowers: "Stuns towers",
};
const LYCH_SOUL = /^SpawnLychSoul\d+$/;

export interface Effect {
  text: string;
  /** a name not in the table: shown as words with an "(internal name)" hint */
  internal?: boolean;
}
/** "RockTimer" → "Rock timer" (CamelCase split into words). */
export function words(name: string): string {
  const s = name.replace(/([a-z0-9])([A-Z])/g, "$1 $2").replace(/([A-Z]+)([A-Z][a-z])/g, "$1 $2").trim();
  return s.charAt(0).toUpperCase() + s.slice(1).toLowerCase();
}
/** One action name in plain words; null for names that are only animation / sound / timers. */
export function effect(name: string): Effect | null {
  if (DROP.has(name)) return null;
  if (LYCH_SOUL.test(name)) return { text: "Spawns Lych souls" };
  const t = ACTION_TEXT[name];
  return t ? { text: t } : { text: words(name), internal: true };
}
/** The model data of one tier that gives the wording its numbers. */
export interface FxCtx {
  actions?: Record<string, ActionModel[]>;
  noModel?: readonly string[];
}
const BLOON_NAME: Record<string, string> = { Moab: "MOAB", Bfb: "BFB", Zomg: "ZOMG", Ddt: "DDT", Bad: "BAD" };
/** A bloon id in words: "CeramicFortified" → "Ceramic fortified", "MiniLych3" → "Lych soul". */
export function bloonName(id: string): string {
  if (/^MiniLych\d*$/.test(id)) return "Lych soul";
  return BLOON_NAME[id] ?? words(id);
}
/** "Spawns 30 Ceramic" from the SpawnBloons models of an action (count + bloon type only); null when it has none. */
function spawnCounts(models: readonly ActionModel[] | undefined): string | null {
  const parts = (models ?? []).filter((m) => m.model === "SpawnBloons" && typeof m.spawnCount === "number" && typeof m.bloonType === "string").map((m) => `${m.spawnCount} ${bloonName(m.bloonType as string)}`);
  return parts.length ? `Spawns ${parts.join(", ")}` : null;
}
/**
 * Stun wording from the action's model. Seconds and the tier-dependent radius confirmed by the owner from play
 * (the data has no unit): Vortex StunTowers stunDuration + radius, Blastapopoulos Fireball stunDuration.
 */
function stunText(name: string, models: readonly ActionModel[] | undefined): string | null {
  const m = (models ?? []).find((x) => x.model === name && typeof x.stunDuration === "number");
  if (!m) return null;
  const s = `${+(m.stunDuration as number).toFixed(2)} s`;
  if (name === "StunTowers") return typeof m.radius === "number" ? `Stuns towers within radius ${m.radius} for ${s}` : `Stuns towers for ${s}`;
  if (name === "Fireball") return `Fireball: stuns its target tower for ${s}`;
  return null;
}
/** A skull's actions in plain words: dropped and unmodelled names gone, spawns with count and bloon, repeated texts once, order kept. */
export function effects(names: readonly string[], ctx: FxCtx = {}): Effect[] {
  const out: Effect[] = [];
  const add = (e: Effect | null) => {
    if (e && !out.some((x) => x.text === e.text)) out.push(e);
  };
  let souls = 0;
  let soulAt = -1;
  for (const n of names) {
    if (ctx.noModel?.includes(n)) continue;
    if (LYCH_SOUL.test(n) && ctx.actions) {
      if (ctx.actions[n]?.some((m) => m.model === "SpawnBloons")) {
        if (!souls) soulAt = out.length;
        souls++;
      }
      continue;
    }
    const sp = spawnCounts(ctx.actions?.[n]) ?? stunText(n, ctx.actions?.[n]);
    add(sp ? { text: sp } : effect(n));
  }
  if (souls) out.splice(soulAt, 0, { text: `Spawns ${souls} Lych soul${souls === 1 ? "" : "s"}` });
  return out;
}
/** True when every skull runs the same effects (shown once as "Every skull: …"). */
export function sameEffects(skulls: readonly BossAction[], ctx: FxCtx = {}): boolean {
  if (skulls.length < 2) return false;
  const key = (s: BossAction) => effects(s.do, ctx).map((e) => e.text).join("|");
  return skulls.every((s) => key(s) === key(skulls[0]));
}

// ─────────────────────────────── always-active wording (passives)

const lc = (t: string) => t.charAt(0).toLowerCase() + t.slice(1);
const grp = (n: number) => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
const sec = (n: number) => `${+n.toFixed(2)} s`;
const isNum = (v: unknown): v is number => typeof v === "number" && Number.isFinite(v);
export interface PassiveLine {
  text: string;
  internal?: boolean;
}
const LYCH_TIMER: Record<string, string> = { drain: "drain", regrow: "regrow", tombstone: "tombstone" };

/** What a timer's actions do, in words; only the decoded facts the page rules allow (seconds, the camo flag). */
function timerBody(names: readonly string[], actions: FxCtx["actions"]): PassiveLine {
  const parts: string[] = [];
  let internal = false;
  const all = names.flatMap((n) => actions?.[n] ?? []);
  const jam = all.some((m) => m.model === "PhayzeTimer");
  const wait = all.find((m) => m.model === "WaitForSeconds" && isNum(m.delayTime))?.delayTime as number | undefined;
  for (const n of names) {
    const m = actions?.[n]?.[0];
    if (m?.model === "PhayzeTimer") parts.push(`Radar Jam, Camo-seeing buffs off${wait !== undefined ? ` for ${sec(wait)}` : ""}`);
    else if ((m?.model === "WaitForSeconds" && jam) || (!m && /(Anim|Sound|Snd)$/.test(n))) continue;
    else if (m?.model === "DestroyProjectiles") parts.push("storm pulse destroys projectiles");
    else if (m?.model === "ThrowBloons") parts.push(m.addCamo === true ? "pulls Bloons to Phayze and gives them Camo" : "pulls Bloons to Phayze");
    else if (m?.model === "RemoveAllDot") parts.push("burns off damage-over-time effects");
    else {
      const e = effect(n);
      if (e) {
        parts.push(lc(e.text));
        internal ||= !!e.internal;
      }
    }
  }
  return { text: parts.join(" · "), internal };
}

/** The always-active lines of one tier: repeating things as "Every …", then the whitelisted stat lines. Unknown kinds / fields never render. */
export function passiveLines(tier: Pick<BossTier, "passives" | "actions" | "noModel">): PassiveLine[] {
  const timers: PassiveLine[] = [];
  const stats: PassiveLine[] = [];
  const ctx: FxCtx = { actions: tier.actions, noModel: tier.noModel };
  for (const p of tier.passives ?? []) {
    const doNames = Array.isArray(p.do) ? (p.do as unknown[]).filter((x): x is string => typeof x === "string") : [];
    if (p.kind === "everyHealth" && isNum(p.step)) {
      const fx = effects(doNames, ctx);
      timers.push({ text: `Every ${+(p.step * 100).toFixed(2)}% of health lost${fx.length ? `: ${fx.map((e) => lc(e.text)).join(" · ")}` : ""}`, internal: fx.some((e) => e.internal) });
    } else if (p.kind === "timer" && isNum(p.seconds)) {
      const named = typeof p.name === "string" ? LYCH_TIMER[p.name] : undefined;
      const body = named ? { text: named + (isNum(p.first) ? `, first after ${sec(p.first)}` : ""), internal: false } : timerBody(doNames, tier.actions);
      timers.push({ text: `Every ${sec(p.seconds)}${p.immediately === true ? ", also at spawn" : ""}${body.text ? `: ${body.text}` : ""}`, internal: body.internal });
    } else if (p.kind === "damageReduction" && isNum(p.amount)) {
      stats.push({ text: p.amount === 0 ? "No damage reduction" : `Takes ${+p.amount.toFixed(2)} less damage from every hit` });
    } else if (p.kind === "phayze" && isNum(p.shieldSpeedBoost)) {
      stats.push({ text: `${mult(p.shieldSpeedBoost)} speed while the Reality Shield is up` });
    } else if (p.kind === "heat" && isNum(p.maxHeatLevel)) {
      stats.push({ text: `Heat limit ${grp(p.maxHeatLevel)}` });
    } else if (p.kind === "diamondback" && isNum(p.numOfMiddleSegments)) {
      stats.push({ text: `${p.numOfMiddleSegments} middle segments` });
    } else if (p.kind === "tombstones" && isNum(p.tombstoneHealthOverride)) {
      stats.push({ text: `Tombstone HP ${grp(p.tombstoneHealthOverride)}` });
    }
  }
  return [...timers, ...stats];
}

/** "Speed in the game's units: Red and MOAB 25 · BFB 6.25 · ZOMG and BAD 4.5": equal values share a group. */
export function speedReference(speed: Record<string, number>): string {
  const groups: { names: string[]; v: number }[] = [];
  for (const k of ["Red", "Moab", "Bfb", "Zomg", "Bad"]) {
    if (!isNum(speed[k])) continue;
    const g = groups.find((x) => x.v === speed[k]);
    if (g) g.names.push(BLOON_NAME[k] ?? k);
    else groups.push({ names: [BLOON_NAME[k] ?? k], v: speed[k] });
  }
  return `Speed in the game's units: ${groups.map((g) => `${g.names.join(" and ")} ${speedVal(g.v)}`).join(" · ")}`;
}
/** The reference bloons by speed, slowest first; equal values share a group ("Red and MOAB" 25). */
function speedGroups(speed: Record<string, number>): { name: string; v: number }[] {
  const groups: { names: string[]; v: number }[] = [];
  for (const k of ["Red", "Moab", "Bfb", "Zomg", "Bad"]) {
    if (!isNum(speed[k])) continue;
    const g = groups.find((x) => x.v === speed[k]);
    if (g) g.names.push(BLOON_NAME[k] ?? k);
    else groups.push({ names: [BLOON_NAME[k] ?? k], v: speed[k] });
  }
  return groups.sort((a, b) => a.v - b.v).map((g) => ({ name: g.names.join(" and "), v: g.v }));
}
/** A boss speed against real bloons, from the data: "slower than ZOMG and BAD (4.5)", "between BFB (6.25) and Red and MOAB (25)". */
export function speedCompare(v: number, speed: Record<string, number>): string {
  const g = speedGroups(speed);
  if (g.length === 0) return "";
  const at = (x: { name: string; v: number }) => `${x.name} (${speedVal(x.v)})`;
  const same = g.find((x) => x.v === v);
  if (same) return `same speed as ${at(same)}`;
  if (v < g[0].v) return `slower than ${at(g[0])}`;
  if (v > g[g.length - 1].v) return `faster than ${at(g[g.length - 1])}`;
  const i = g.findIndex((x) => x.v > v);
  return `between ${at(g[i - 1])} and ${at(g[i])}`;
}

/** The one stretch every row shares ("every skull: 326,250 shield + 326,250 HP"), or null when any two differ. */
/**
 * The one stretch every skull shares, or null. Within 0.1% counts as shared (Lych's thresholds are stored as
 * 0.8333 / 0.6666 …, so its stretches differ by a few HP); `approx` is then true and the page prefixes "≈".
 */
export function commonStretch(rows: readonly SkullRow[]): { row: SkullRow; approx: boolean } | null {
  if (rows.length < 2) return null;
  const near = (a: number, b: number) => Math.abs(a - b) <= Math.max(a, b) * 0.001;
  if (!rows.every((r) => near(r.hp, rows[0].hp) && near(r.shield, rows[0].shield))) return null;
  return { row: rows[0], approx: rows.some((r) => r.hp !== rows[0].hp || r.shield !== rows[0].shield) };
}

/** A speed value as the game holds it, up to 3 decimals. */
export const speedVal = (v: number) => `${+v.toFixed(3)}`;

/** Spawn names for the page: the data has none (null). */
export const SPAWN_NAME: Record<string, string> = {
  MiniLych: "Lych soul",
  Tombstone: "Tombstone",
  DreadRockBloon: "Rock bloon",
  DiamondbackDiamondBloon: "Diamond bloon",
};
export const spawnName = (s: Pick<BossSpawn, "key" | "name">) => s.name ?? SPAWN_NAME[s.key] ?? words(s.key);

/**
 * Minimum kill time of one tier, with instant damage between the phases: only what damage can't shorten is left.
 * All from the game data: the entrance and death animations (SpawnDeathAnimModel), and at each skull the time from
 * "invulnerable on" to "invulnerable off" along the skull's wait chain (Vortex 0.5 s, Blastapopoulos 2 s, Phayze 2 s
 * then its warp) or Diamondback's skullInvulnerableTime. Shields and Lych's ethereal phase cost no time here: instant
 * damage breaks a shield and pops every Lych soul as it appears. Phayze's warp covers a share of the map's path, so
 * its length isn't in the boss data: `warps` counts them instead of adding seconds.
 */
export interface KillTime {
  spawn: number;
  death: number;
  /** invulnerable seconds at each skull, in skull order */
  skulls: number[];
  /** Phayze: warps not in the seconds (one per skull) */
  warps: number;
  total: number;
}
export function killTime(tier: Pick<BossTier, "skulls" | "passives" | "actions">, skipOne = false): KillTime | null {
  const anim = tier.passives?.find((p) => p.kind === "anim");
  if (!anim || !isNum(anim.spawn) || !isNum(anim.death)) return null;
  const actions = tier.actions ?? {};
  const back = tier.passives?.find((p) => p.kind === "diamondback")?.skullInvulnerableTime;
  // seconds from the skull to "invulnerable off" along the wait chain; dash = a DashForwards on the way
  const off = (ids: readonly string[], t: number, dash: boolean, seen: Set<string>): { t: number; dash: boolean } | null => {
    for (const id of ids) {
      if (seen.has(id)) continue;
      seen.add(id);
      for (const m of actions[id] ?? []) {
        if (m.model === "SetInvulnerable" && m.set === false) return { t, dash };
        const then = Array.isArray(m.then) ? (m.then as string[]) : [];
        const r =
          m.model === "WaitForSeconds" && isNum(m.delayTime) ? off(then, t + m.delayTime, dash, seen)
          : m.model === "DashForwards" ? off(then, t, true, seen)
          : null;
        if (r) return r;
      }
    }
    return null;
  };
  const per = tier.skulls.map((s) => {
    const on = s.do.some((id) => (actions[id] ?? []).some((m) => m.model === "SetInvulnerable" && m.set === true));
    const r = on ? off(s.do, 0, false, new Set()) : null;
    return r ?? { t: isNum(back) ? back : 0, dash: false };
  });
  // Herald of Everfrost's Eclipse of Fimbulwinter cancels one skull per tier: drop the longest
  if (skipOne && per.length) {
    const i = per.reduce((b, x, k) => (x.t + +x.dash > per[b].t + +per[b].dash ? k : b), 0);
    per.splice(i, 1);
  }
  const skulls = per.map((x) => x.t);
  const total = anim.spawn + skulls.reduce((a, b) => a + b, 0) + anim.death;
  return { spawn: anim.spawn, death: anim.death, skulls, warps: per.filter((x) => x.dash).length, total: +total.toFixed(3) };
}
/** "16 s", "12 s + 3 warps" */
export const killText = (k: KillTime) => `${sec(k.total)}${k.warps ? ` + ${k.warps} warp${k.warps > 1 ? "s" : ""}` : ""}`;
/** The sum behind one tier's time: ["Entrance 3 s", "4 skulls × 2 s invulnerable", "Defeat animation 5 s"]. */
export function killParts(k: KillTime): string[] {
  const n = k.skulls.length;
  const same = k.skulls.every((x) => x === k.skulls[0]);
  const skulls =
    n === 0 ? "no skulls left"
    : k.skulls.every((x) => x === 0) ? `${n} skull${n > 1 ? "s" : ""}, no invulnerable time`
    : same ? `${n} skull${n > 1 ? "s" : ""} × ${sec(k.skulls[0])} invulnerable`
    : `skulls ${k.skulls.map(sec).join(" + ")} invulnerable`;
  return [`Entrance ${sec(k.spawn)}`, skulls, `Defeat animation ${sec(k.death)}`];
}
/** Phayze: the share of the path one warp covers (DashForwards.dashDistance), or undefined. */
export function warpShare(tier: Pick<BossTier, "actions">): number | undefined {
  const d = Object.values(tier.actions ?? {}).flat().find((m) => m.model === "DashForwards")?.dashDistance;
  return isNum(d) ? d : undefined;
}
